import "forge-std/Test.sol";
import "./AddressCast.sol";

contract AddressCastTest is Test {
    using AddressCast for uint256;

    function testUnsafeCastingLeadsToIncorrectAddress() public {
        // Original uint256 with data in the upper 96 bits
        uint256 originalValue = uint256(0x1234567890abcdef1234567890abcdef1234567890abcdef1234567890abcdef);

        // Cast to address using the vulnerable function
        address result = originalValue.to_address();

        // Expected address after truncation (only the lower 160 bits)
        address expected = address(uint160(originalValue));

        // Assert that the result is the truncated address
        assertEq(result, expected, "The address should be truncated to the lower 160 bits");
    }
}
```

